#!/usr/bin/env bash
# GPU part of the reproduction: TabImpute V2 as the imputation backend
# (figures/tabimpute_r2_*.pdf).  Everything else is CPU-only and is
# regenerated by run_all.sh.
#
# Usage:
#
#   BENCHSELECT_EXPERIMENT_ROOT=/scratch/benchselect-run \
#   BENCHSELECT_TABIMPUTE_DEVICE=cuda:1 BENCHSELECT_DATASETS=merged \
#   PYTHON=~/venvs/tabimpute/bin/python \
#       bash code/run_tabimpute.sh [--dry-run] [--list]
#
# For each dataset in BENCHSELECT_DATASETS (comma separated; default
# mmlu,mteb,merged,benchpress; any name with a <name>.matrix.npz in the data
# directory) two jobs run, one after the other:
#   tabimpute_<ds>        eval_tabimpute.py with its default methods
#                         (entropy, mi, random, facloc; entropy_rf was
#                         dropped, protocol rule D3) ->
#                         logs/tabimpute_<ds>.npz,
#                         logs/tabimpute_<ds>_paired.csv,
#                         figures/tabimpute_r2_<ds>.pdf
#   tabimpute_extra_<ds>  BENCHSELECT_METHODS=hub,pca,trace, which
#                         eval_tabimpute.py saves under its "extra_" tag ->
#                         logs/tabimpute_extra_<ds>.npz,
#                         logs/tabimpute_extra_<ds>_paired.csv,
#                         figures/tabimpute_r2_extra_<ds>.pdf
# Each job runs eval_tabimpute.py with BENCHSELECT_DATASETS=<ds> and
# --repeats $BENCHSELECT_TABIMPUTE_REPEATS (default 1).  Facility location
# (facloc, the paper's headline method) joined the default job on
# 2026-10-19; the jobs keep their earlier method sets otherwise (default
# entropy, mi, random; extra hub, pca, trace), so the extra job's outputs
# and every array of the default log are those of a run before facloc.
# make_numbers.py and paired_stats.py read the methods of both logs of a
# dataset as one table (facloc - trace etc. come from there), so the
# macros do not depend on which job ran a method.
#
# GPU time: within a job, a selected set that several methods (or k)
# share is imputed once per split, so a job's time scales with its
# distinct sets per split (eval_tabimpute.py prints "TabImpute: N
# imputations").  The rep-0 tabimpute_mmlu job of entropy, mi, random took
# 29 min on an RTX 4090 (about 4 s per imputation; MTEB 0.1 s, Merged and
# BenchPress 0.2 s).  BENCHSELECT_TABIMPUTE_REPEATS=5 with these method
# sets: about 6.6 h on one RTX 4090 (from the call counts and the 6.5 h
# of a 2026-10-19 run of the same code with trace in the default job:
# MMLU 5.6 h, 3.2 h default and 2.4 h extra job; MTEB 10 min, Merged and
# BenchPress 25 min each).
#
# Adding facloc to the logs of an earlier run of the sets without facloc
# (no rerun of the other methods): run only facloc into a second root and
# combine, without a GPU (eval_tabimpute.py --merge-from, module docstring
# "Combining runs"):
#   BENCHSELECT_EXPERIMENT_ROOT=NEW BENCHSELECT_TABIMPUTE_DEVICE=cuda:0 \
#   BENCHSELECT_DATASETS=mmlu BENCHSELECT_METHODS=facloc \
#       "$PYTHON" code/eval_tabimpute.py
#   (cd code && BENCHSELECT_EXPERIMENT_ROOT=OUT "$PYTHON" eval_tabimpute.py \
#       --datasets mmlu --merge-from OLD/logs/tabimpute_{ds}.npz \
#       NEW/logs/tabimpute_extra_{ds}.npz &&
#     BENCHSELECT_EXPERIMENT_ROOT=OUT "$PYTHON" eval_tabimpute.py \
#       --datasets mmlu --methods hub pca trace \
#       --merge-from OLD/logs/tabimpute_extra_{ds}.npz)
# writes into OUT exactly the logs, paired CSVs and figures of this
# script's two jobs (OLD: the root of the earlier run).
#
# Splits: the matched design of cv_split.cv_splits, shared with the CPU runs
# (same train / validation models, eligible benchmarks and random numbers per
# split; split_id = rep * 10 + fold in the logs).  GPU time is scarce, so by
# default only repetition 0 runs: the original seed-42 10-fold split, which
# is rep 0 (split_id 0-9) of run_all.sh's 5 x 10 design.
# BENCHSELECT_TABIMPUTE_REPEATS=5 runs all 50 splits.  The paired CSVs
# compare the methods of one job; the two jobs' logs pair on split_id.
#
# BENCHSELECT_TABIMPUTE_DEVICE is required (cuda:N or cpu) and passed through
# unchanged (as is CUDA_VISIBLE_DEVICES), so the caller places datasets on
# chosen GPUs, e.g. one invocation per GPU into the same root:
#   BENCHSELECT_DATASETS=mmlu,mteb  BENCHSELECT_TABIMPUTE_DEVICE=cuda:0 bash code/run_tabimpute.sh &
#   BENCHSELECT_DATASETS=merged     BENCHSELECT_TABIMPUTE_DEVICE=cuda:1 bash code/run_tabimpute.sh &
#   BENCHSELECT_DATASETS=benchpress BENCHSELECT_TABIMPUTE_DEVICE=cuda:2 bash code/run_tabimpute.sh &
#
# RUN_ONLY (jobs or the groups tabimpute / tabimpute_extra), MAX_JOBS
# (default 1 here: an invocation's jobs share one device), PYTHON,
# BENCHSELECT_ALLOW_UNPINNED, BENCHSELECT_GIT_*, --dry-run, --list, the exit
# status and the outputs (stdout/<job>.txt, single-threaded BLAS,
# PYTHONHASHSEED=0, artifact origins, ...) follow run_all.sh, whose helpers
# this script sources.  The interpreter is checked against the lock
# requirements-tabimpute.txt.  The manifest goes to
# manifest_tabimpute_<datasets>.json (archived in manifests/), one per
# dataset list, so concurrent per-GPU invocations do not overwrite each
# other.  Afterwards, RUN_ONLY=numbers bash code/run_all.sh into the same
# root adds the TabImpute numbers to numbers/.
#
# Weights: eval_tabimpute.py loads tabimputev2.ckpt from the Hugging Face Hub
# repo Tabimpute/TabImpute at the pinned commit CKPT_REVISION (727574989dde...,
# the repo's main on 2026-10-17; downloaded once into the HF cache) and exits
# unless its sha256 is CKPT_SHA256 (b48b5bfd..., the same LFS object as at
# 96d7a0f1, the cached revision of the earlier unpinned runs, validated on
# 4090-2 on 2026-07-27).  BENCHSELECT_TABIMPUTE_CKPT_SHA256 overrides the
# expected hash for both that check and the manifest.  Revision and sha256
# are saved in every log (ckpt_revision, ckpt_sha256).  The manifest records
# the cached file too (hf_files) when the HF cache has a refs/main for the
# repo: run_all.sh's helper looks the file up through that ref, which a
# download at a pinned commit does not write, so on a cache holding only the
# pinned snapshot the logs are the record.
#
# Determinism: TabImputeV2 inference draws no random numbers (eval mode,
# dropout 0, bar-distribution median).  eval_tabimpute.py requests torch's
# deterministic algorithms (warn_only), cuDNN deterministic mode without
# benchmarking and a fixed seed, and CUBLAS_WORKSPACE_CONFIG=:4096:8 (unless
# set by the caller) fixes cuBLAS's workspace.  bf16 results can still
# differ across GPU models, CUDA or torch versions.

set -euo pipefail

BS_DRIVER=run_tabimpute
# shellcheck source=run_all.sh
source "$(dirname "${BASH_SOURCE[0]}")/run_all.sh"

# The validated TabImputeV2 checkpoint (see "Weights" above; the revision
# is pinned in eval_tabimpute.py).
TABIMPUTE_CKPT=Tabimpute/TabImpute:tabimputev2.ckpt
TABIMPUTE_CKPT_SHA256=${BENCHSELECT_TABIMPUTE_CKPT_SHA256:-b48b5bfdaf496bb949b762377518cd4ddeea7629e44f02aebb9a18ca9e711bce}

BS_START=$(bs_now)
bs_parse_args "$@"
MAX_JOBS=${MAX_JOBS:-1}
bs_init_paths

TABIMPUTE_REPEATS=${BENCHSELECT_TABIMPUTE_REPEATS:-1}
[[ $TABIMPUTE_REPEATS =~ ^[1-9][0-9]*$ ]] ||
    bs_die "BENCHSELECT_TABIMPUTE_REPEATS must be a positive integer, got '$TABIMPUTE_REPEATS'"

# Read the caller's dataset list before bs_export_env clears the variable;
# every job then sets BENCHSELECT_DATASETS to its own single dataset.
TABIMPUTE_DATASETS=${BENCHSELECT_DATASETS:-mmlu,mteb,merged,benchpress}
read -r -a ds_list <<<"${TABIMPUTE_DATASETS//,/ }" || true
(( ${#ds_list[@]} )) || bs_die "BENCHSELECT_DATASETS is empty"
for ds in "${ds_list[@]}"; do
    if [[ ! $ds =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ || ! -f $BS_DATA_DIR/$ds.matrix.npz ]]; then
        avail=$(cd "$BS_DATA_DIR" 2>/dev/null && for f in *.matrix.npz; do
                    [[ -f $f ]] && printf '%s ' "${f%.matrix.npz}"; done)
        bs_die "unknown dataset '$ds' in BENCHSELECT_DATASETS: no $BS_DATA_DIR/$ds.matrix.npz (available: ${avail% })"
    fi
    bs_job "tabimpute_$ds" tabimpute "" \
        "logs/tabimpute_$ds.npz logs/tabimpute_${ds}_paired.csv figures/tabimpute_r2_$ds.pdf" \
        env BENCHSELECT_DATASETS="$ds" "$BS_PYTHON" eval_tabimpute.py \
        --repeats "$TABIMPUTE_REPEATS"
    bs_job "tabimpute_extra_$ds" tabimpute_extra "" \
        "logs/tabimpute_extra_$ds.npz logs/tabimpute_extra_${ds}_paired.csv figures/tabimpute_r2_extra_$ds.pdf" \
        env BENCHSELECT_DATASETS="$ds" BENCHSELECT_METHODS=hub,pca,trace \
        "$BS_PYTHON" eval_tabimpute.py --repeats "$TABIMPUTE_REPEATS"
done
if (( BS_LIST )); then
    bs_list_jobs
    exit 0
fi

[[ -n ${BENCHSELECT_TABIMPUTE_DEVICE:-} ]] ||
    bs_die "BENCHSELECT_TABIMPUTE_DEVICE is not set; choose the device explicitly (e.g. cuda:1, or cpu)"
bs_init_root
bs_select
bs_export_env
BS_ENV_SET+=(BENCHSELECT_TABIMPUTE_DEVICE)
if [[ -v CUDA_VISIBLE_DEVICES ]]; then
    BS_ENV_SET+=(CUDA_VISIBLE_DEVICES)
fi
if [[ -v BENCHSELECT_TABIMPUTE_CKPT_SHA256 ]]; then
    BS_ENV_SET+=(BENCHSELECT_TABIMPUTE_CKPT_SHA256)
fi
bs_setenv CUBLAS_WORKSPACE_CONFIG "${CUBLAS_WORKSPACE_CONFIG:-:4096:8}"
BS_REQUIREMENTS=$BS_REPO/requirements-tabimpute.txt
ds_tag=$(IFS=+; printf '%s' "${ds_list[*]}")
BS_MANIFEST=$BS_ROOT/manifest_tabimpute_$ds_tag.json
if (( BS_DRY_RUN )); then
    bs_print_plan
    exit 0
fi
bs_prepare_root --gpu-info
bs_run_selected
# The HF cache as huggingface_hub (and run_all.sh's hf_cache_dir) finds it.
hf_cache=${HF_HUB_CACHE:-${HF_HOME:+$HF_HOME/hub}}
hf_cache=$(bs_expand_home "${hf_cache:-${XDG_CACHE_HOME:-$HOME/.cache}/huggingface/hub}")
hf_repo=${TABIMPUTE_CKPT%%:*}
hf_repo_dir=$hf_cache/models--${hf_repo//\//--}
if [[ -f $hf_repo_dir/refs/main ]]; then
    BS_MANIFEST_FLAGS=(--hf-file "$TABIMPUTE_CKPT${TABIMPUTE_CKPT_SHA256:+@$TABIMPUTE_CKPT_SHA256}")
else
    bs_log "note: no $hf_repo_dir/refs/main (pinned-commit download only); the manifest does not list the checkpoint, the logs' ckpt_revision / ckpt_sha256 record it"
fi
rc=0
bs_finish || rc=$?
exit "$rc"
